package protectedby_test

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"testing"

	"golang.org/x/tools/go/analysis"
	"golang.org/x/tools/go/analysis/passes/inspect"
	"golang.org/x/tools/go/ast/inspector"
	"golang.org/x/tools/go/packages"

	"github.com/mneverov/protectedby/protectedby"
)

// benchCases are the packages BenchmarkRun analyzes. The std packages contain "protected by" comments. synth is
// generated by writeSynth because std has few protected accesses per file.
var benchCases = []struct{ name, pattern string }{
	{"go-token", "go/token"},
	{"crypto-tls", "crypto/tls"},
	{"net-http", "net/http"},
	{"runtime", "runtime"},
	{"synth", "synth"},
}

// BenchmarkRun measures Analyzer.Run on preloaded packages. The inspector is built outside the timer: the driver
// builds it for inspect.Analyzer, which Analyzer requires, and shares it with other analyzers under go vet.
// The diags metric is the number of reported diagnostics, so a comparison also shows a change in behavior.
// Run "make bench-compare" to compare with another revision.
func BenchmarkRun(b *testing.B) {
	for _, tc := range benchCases {
		b.Run(tc.name, func(b *testing.B) {
			pass := loadPass(b, tc.pattern)
			var diags int
			pass.Report = func(analysis.Diagnostic) { diags++ }
			for b.Loop() {
				diags = 0
				if _, err := protectedby.Analyzer.Run(pass); err != nil {
					b.Fatal(err)
				}
			}
			b.ReportMetric(float64(diags), "diags")
		})
	}
}

var (
	passesMu sync.Mutex
	passes   = map[string]*analysis.Pass{}
)

// loadPass loads the package once per process, because -count runs BenchmarkRun several times.
func loadPass(b *testing.B, pattern string) *analysis.Pass {
	passesMu.Lock()
	defer passesMu.Unlock()
	if p, ok := passes[pattern]; ok {
		return p
	}

	cfg := &packages.Config{Mode: packages.LoadAllSyntax}
	if pattern == "synth" {
		dir, err := os.MkdirTemp("", "protectedby-synth")
		if err != nil {
			b.Fatal(err)
		}
		defer os.RemoveAll(dir)
		if err := writeSynth(dir); err != nil {
			b.Fatal(err)
		}
		cfg.Dir, pattern = dir, "."
	}
	pkgs, err := packages.Load(cfg, pattern)
	if err != nil {
		b.Fatal(err)
	}
	if len(pkgs) != 1 || len(pkgs[0].Errors) > 0 {
		b.Fatalf("load %s: %v", pattern, pkgs)
	}

	pkg := pkgs[0]
	p := &analysis.Pass{
		Analyzer:   protectedby.Analyzer,
		Fset:       pkg.Fset,
		Files:      pkg.Syntax,
		Pkg:        pkg.Types,
		TypesInfo:  pkg.TypesInfo,
		TypesSizes: pkg.TypesSizes,
		ResultOf:   map[*analysis.Analyzer]any{inspect.Analyzer: inspector.New(pkg.Syntax)},
	}
	passes[pattern] = p
	return p
}

// writeSynth writes the synthetic module into dir: one file with 100 structs and 2000 functions. Each function
// locks a struct, defers the unlock, and accesses protected fields 4 times; 2 of them follow an Unlock() in a branch,
// which the analyzer reports because the order is lexical. Analysis time on large files grows with
// file size x accesses if the analyzer walks the file from its root for every access.
func writeSynth(dir string) error {
	const structs, funcs = 100, 2000

	var sb strings.Builder
	sb.WriteString("package synth\n\nimport \"sync\"\n")
	for i := range structs {
		fmt.Fprintf(&sb, `
type s%d struct {
	// a is protected by mu.
	a int
	// m is protected by mu.
	m  map[string]int
	mu sync.RWMutex
}
`, i)
	}
	for j := range funcs {
		fmt.Fprintf(&sb, `
func f%d(x *s%d) int {
	x.mu.Lock()
	defer x.mu.Unlock()
	x.a++
	x.m["k"] = x.a
	if x.a > 10 {
		x.mu.Unlock()
		return x.a
	}
	return len(x.m)
}
`, j, j%structs)
	}

	if err := os.WriteFile(filepath.Join(dir, "go.mod"), []byte("module synth\n\ngo 1.22\n"), 0o644); err != nil {
		return err
	}
	return os.WriteFile(filepath.Join(dir, "synth.go"), []byte(sb.String()), 0o644)
}
